  // Точка над узлом полосы: живой прямоугольник, а без раскладки (стенд) — та же арифметика,
  // что поставила узлам left/top.
  const rickAnchor = node => {
    const rect = rickRect(node);
    if (rect) return { left: rect.left, top: rect.top };
    const read = (item, name) => parseFloat(item?.style?.getPropertyValue(name)) || 0;
    let left = read(rickNode, "left");
    let top = read(rickNode, "top") - (Number(rickList.scrollTop) || 0);
    for (let item = node; item && item !== rickNode; item = item.parentNode) { left += read(item, "left"); top += read(item, "top"); }
    return { left, top };
  };
  // Полоска марафона (WF201): клетка под курсором — по x (шаг клетки из data-pitch), наведение — её ячейка
  // «45 •» над клеткой (тот же вид, что в строке, правило №2) с ножкой, клетка светится; ушёл с полоски —
  // гаснет. Клик по клетке — карточка этого Workflow, как по ячейке.
  const rickStripOf = node => (node?.dataset?.strip ? node : (node?.parentNode?.dataset?.strip ? node.parentNode : null));
  function rickStripIndex(bar, clientX) {
    const pitch = Number(bar?.dataset?.pitch) || RICK_STRIP_PITCH;
    const count = Number(bar?.dataset?.cells) || 1;
    const x = Number(clientX);
    if (!Number.isFinite(x)) return 0;
    return Math.max(0, Math.min(count - 1, Math.floor((x - rickAnchor(bar).left) / pitch)));
  }
  // Отрезок полоски с клеткой at (WF204: слитые готовые — один отрезок): from…to по порядку и состояние.
  function rickStripSpan(bar, at) {
    for (const part of bar?.children ?? []) {
      if (part.dataset?.mark || part.dataset?.from === undefined) continue;
      const from = Number(part.dataset.from);
      const to = Number(part.dataset.to);
      if (at >= from && at <= to) return { from, to, state: part.dataset.state || "plan" };
    }
    return { from: at, to: at, state: "" };
  }
  // Свет отрезка с клеткой at: kind "picked" — её карточка открыта, "hover" — под курсором.
  function rickStripMark(bar, at, kind) {
    for (const old of [...bar.children]) if (old.dataset?.mark === kind) old.remove();
    const pitch = Number(bar.dataset.pitch) || RICK_STRIP_PITCH;
    const gap = Number(bar.dataset.gap) || 0;
    const { from, to } = rickStripSpan(bar, at);
    const mark = document.createElement("u");
    mark.dataset.mark = kind;
    mark.style.setProperty("left", `${from * pitch}px`);
    mark.style.setProperty("width", `${Math.max(1, (to - from + 1) * pitch - gap)}px`);
    bar.appendChild(mark);
    return mark;
  }
  function rickHoverHide() {
    const hover = rickState.hover;
    rickState.hover = null;
    if (hover?.bar) for (const old of [...hover.bar.children]) if (old.dataset?.mark === "hover") old.remove();
    const tip = rickState.tip;
    if (tip && tip.style.getPropertyValue("display") !== "none") tip.style.setProperty("display", "none");
  }
  // Слитый отрезок (WF204) — ячейка «WF175–WF196 · готово», свет на весь отрезок; клик — последний из него.
  function rickHoverShow(bar, index) {
    const key = bar.parentNode?.dataset?.key;
    const project = (rickState.projects ?? []).find(item => rickKey(item) === key);
    const span = rickStripSpan(bar, index);
    const at = span.from;
    const flow = project?.workflows[span.to];
    if (!flow) { rickHoverHide(); return; }
    if (rickState.hover?.bar === bar && rickState.hover.at === at) return;
    rickHoverHide();
    const cell = rickCell(flow, project);
    if (span.to > span.from) {
      const first = rickCell(project.workflows[span.from], project);
      cell.label = `WF${first.n}–WF${cell.n} · ${RICK_WORDS[cell.state] ?? cell.state}`;
    }
    rickStripMark(bar, at, "hover");
    rickState.hover = { bar, at, key, n: cell.n };
    let tip = rickState.tip;
    if (!tip) {
      tip = document.createElement("i");
      tip.dataset.tip = "true";
      tip.setAttribute("aria-hidden", "true");
      rickState.tip = tip;
    }
    if (tip.parentNode !== rickNode) rickNode.appendChild(tip);
    tip.textContent = cell.label;
    tip.dataset.state = cell.state || "plan";
    const size = progressBadgeWidth(cell.label) + (cell.state === "run" ? RICK_RUN_DOT : 0);
    const read = name => parseFloat(rickNode.style.getPropertyValue(name)) || 0;
    const origin = rickRect(rickNode) ?? { left: read("left"), top: read("top") };
    const spot = rickAnchor(bar);
    const pitch = Number(bar.dataset.pitch) || RICK_STRIP_PITCH;
    const gap = Number(bar.dataset.gap) || 0;
    const mid = spot.left - origin.left + (at * pitch + (span.to + 1) * pitch - gap) / 2;
    const room = read("width") || mid + size;
    const tipLeft = Math.max(0, Math.min(room - size, mid - size / 2));
    tip.style.setProperty("left", `${Math.round(tipLeft * 2) / 2}px`);
    tip.style.setProperty("top", `${Math.round(spot.top - origin.top + (RICK_ROW_HEIGHT - RICK_STRIP_HEIGHT) / 2 - 4 - PROGRESS_BADGE_HEIGHT)}px`);
    tip.style.setProperty("width", `${size}px`);
    tip.style.setProperty("--sx", `${Math.round((mid - tipLeft) * 2) / 2}px`);
    tip.style.setProperty("display", "block");
  }
  on(rickNode, "pointermove", event => {
    if (!state.alive) return;
    const bar = rickStripOf(event.target);
    if (!bar || rickNode.dataset.fold === "true") { if (rickState.hover) rickHoverHide(); return; }
    rickHoverShow(bar, rickStripIndex(bar, event.clientX));
  });
  on(rickNode, "pointerout", event => { if (rickState.hover && !rickStripOf(event.relatedTarget)) rickHoverHide(); });
  // Клик: фильтр; «Показать» / «Свернуть» (поднятое и раскрытые строки разом); «1–14 ✓» и «+K» —
  // раскрыть строку;
  // «+N проектов» — показать все; капсула (и готовая в раскрытой строке) — карточка Workflow; имя —
  // сводка проекта (повторный клик по тому же — закрыть). Панель PMP — только кнопкой в сводке.
  on(rickNode, "click", event => {
    event.preventDefault();
    event.stopPropagation();
    if (!state.alive || Number(event.detail) > 1 || event.target === rickNode || event.target === rickList || event.target === rickNav) return;
    rickState.touchedAt = now();
    const target = event.target;
    if (target?.dataset?.act === "report" && target.parentNode === rickNav) { try { rickReport(); } catch {} return; }
    if (target?.dataset?.filter) { rickFilterSet(target.dataset.filter); return; }
    if (target?.dataset?.raise) {
      rickState.raised = target.dataset.raise === "on";
      if (!rickState.raised) rickState.open.clear();
      rickEscWatch();
      placeRickCells();
      return;
    }
    // Шеврон вида (WF183): full ↔ none; из «none» с набранным текстом — сразу поверх текста.
    if (target?.dataset?.view && target.parentNode === rickNav) {
      const next = target.dataset.view;
      rickViewSet(next);
      rickState.raised = next === "full" && rickState.typed;
      rickEscWatch();
      placeRickCells();
      return;
    }
    const tag = String(target?.tagName ?? "").toUpperCase();
    // Строка — узел прямо в списке: имя, ячейка, счёт «1 из 10» (и его числа), полоска и её клетки.
    // Узел строки — <s> (снятая перерисовкой строка тоже: её ключ ещё нужен повторному клику).
    let row = target;
    while (row && row !== rickNode && String(row.tagName ?? "").toUpperCase() !== "S") row = row.parentNode;
    if (row === rickNode) row = null;
    const key = row?.dataset?.key;
    if (row?.dataset?.state === "more") { rickState.raised = true; rickEscWatch(); placeRickCells(); return; }
    // Счёт марафона (WF201) — как «1–N ✓»: раскрыть строку по одному.
    const tally = target?.dataset?.count === "true" ? target : (target?.parentNode?.dataset?.count === "true" ? target.parentNode : null);
    const act = tag === "I" ? target.dataset.act ?? "" : (tally ? "open" : "");
    if (key && act) {
      if (act === "open" && rickState.view !== "full") rickViewSet("full");
      if (act === "open") rickState.open.add(key); else rickState.open.delete(key);
      placeRickCells();
      // Раскрытая строка не влезла в рамку — полоса поднимается, а не прячет её в «+N проектов».
      if (act === "open" && rickState.more > 0) { rickState.raised = true; placeRickCells(); }
      rickEscWatch();
      return;
    }
    if (!key) return;
    const card = rickState.card;
    const bar = rickStripOf(target);
    if (bar) {
      const project = (rickState.projects ?? []).find(item => rickKey(item) === key);
      const flow = project?.workflows[rickStripSpan(bar, rickStripIndex(bar, event.clientX)).to];
      if (!flow) return;
      const n = String(rickCell(flow, project).n);
      if (card?.kind === "flow" && card.key === key && card.n === n) { rickCardHide(); return; }
      rickCardShow("flow", key, n);
      return;
    }
    if (tag === "I" && target.dataset.n !== undefined) {
      if (card?.kind === "flow" && card.key === key && card.n === target.dataset.n) { rickCardHide(); return; }
      rickCardShow("flow", key, target.dataset.n);
      return;
    }
    if (card?.kind === "project" && card.key === key) { rickCardHide(); return; }
    rickCardShow("project", key, null);
  });
  // Нажатие по полосе и её карточкам — только наше: фокус поля не уходит, а до слушателей Claude на
  // document (закрыть или открыть своё меню по нажатию) событие не всплывает (#9181). «Клик мимо»
  // карточки (rickOutside) слушает фазу захвата — ему это не мешает.
  const rickKeep = event => { event.preventDefault(); event.stopPropagation(); };
  on(rickNode, "pointerdown", rickKeep);
  on(rickNode, "mousedown", rickKeep);
  on(rickCard, "click", event => {
    event.preventDefault();
    event.stopPropagation();
    const card = rickState.card;
    if (!state.alive || !card) return;
    const tag = String(event.target?.tagName ?? "").toUpperCase();
    if (tag === "BUTTON") { rickCardHide(); try { pmpOpen(); } catch {} return; }
    if (event.target?.dataset?.act === "done") { rickState.cardDone = !rickState.cardDone; rickCardPaint(); return; }
    const item = tag === "LI" ? event.target : (tag === "I" || tag === "SPAN" ? event.target.parentNode : null);
    if (item?.dataset?.n !== undefined && card.kind === "project") rickCardShow("flow", card.key, item.dataset.n);
  });
  for (const node of [rickCard, rickFlow.tip]) {
    on(node, "pointerdown", rickKeep);
    on(node, "mousedown", rickKeep);
    if (node === rickFlow.tip) on(node, "click", event => { event.preventDefault(); event.stopPropagation(); });
  }
  // Клик мимо карточки и полосы — закрыть карточку.
  const rickOutside = event => {
    if (!rickState.card) return;
    const target = event.target;
    if (target && (rickCard.contains?.(target) || rickFlow.tip.contains?.(target) || rickNode.contains?.(target))) return;
    rickCardHide();
  };
  // Esc слушаем, только пока что-то открыто (на чужих страницах и в покое клавишу не трогаем):
  // сперва карточку, потом поднятую полосу, потом раскрытые строки.
  const rickEsc = event => {
    if (event.key !== "Escape" || !state.alive) return;
    const fresh = now() - rickState.touchedAt < RICK_ESC_MS;
    if (rickState.card) {
      rickCardHide();
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (rickState.raised) rickState.raised = false; else rickState.open.clear();
    rickEscWatch();
    if (fresh) {
      event.preventDefault();
      event.stopPropagation();
    }
    rickState.touchedAt = -Infinity;
    try { placeRickCells(); } catch {}
  };
